import sys
from collections import defaultdict

sys.setrecursionlimit(300000)

def dfs(node, parent, graph, leaf_count):
    is_leaf = True
    for neighbor in graph[node]:
        if neighbor != parent:
            is_leaf = False
            dfs(neighbor, node, graph, leaf_count)
    if is_leaf:
        leaf_count[0] += 1

def solve(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    leaf_count = [0]
    dfs(1, -1, graph, leaf_count)
    return leaf_count[0]

def main():
    t = int(sys.stdin.readline().strip())
    results = []
    for _ in range(t):
        n = int(sys.stdin.readline().strip())
        edges = []
        for _ in range(n - 1):
            u, v = map(int, sys.stdin.readline().strip().split())
            edges.append((u, v))
        results.append(solve(n, edges))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
